/**
 * Claude Code's local slash commands, read out of the user channel.
 *
 * WHAT THE HARNESS WRITES. Running `/model opus[1m]` in Claude Code leaves up to
 * three USER records in the transcript, because the user channel is the only one
 * the harness reads back:
 *
 *   <local-command-caveat>Caveat: The messages below were generated by the user
 *     while running local commands. DO NOT respond to these messages …</local-command-caveat>
 *   <command-name>/model</command-name>
 *     <command-message>model</command-message>
 *     <command-args>opus[1m]</command-args>
 *   <local-command-stdout>Set model to ESC[1mOpus 5.5 (1M context)ESC[22m</local-command-stdout>
 *
 * Without this module each of those renders as a "You" bubble full of markup the
 * human never typed. The transcript instead shows ONE compact command row —
 * `/model opus[1m] → Set model to Opus 5.5 (1M context)` — and never shows the
 * caveat, which is an instruction to the model, not something anybody said.
 *
 * DEGRADE DIRECTION. A record is only claimed when EVERY non-blank character of
 * it sits inside one of the six known tags. Anything else left over means a human
 * wrote prose around the markup, and that record stays an ordinary message: the
 * failure mode is a command shown as a bubble (today's status quo), never a human
 * sentence demoted into a muted command row.
 *
 * CODEX HAS NO EQUIVALENT TO PARSE. Its TUI handles slash commands locally and
 * writes no user record for them, so there is nothing of Codex's to recognise
 * here; a Codex transcript simply never matches.
 */

/** `ok` for standard output (or none), `err` once the command wrote to stderr. */
export type SlashCommandTone = 'ok' | 'err';

/** One slash command as the transcript shows it. */
export interface SlashCommand {
  /** `/model`. Empty when only the command's output survived in the loaded window. */
  readonly name: string;
  /** `opus[1m]`, or absent for a command run with no arguments. */
  readonly args?: string;
  /** What the command printed, colour codes removed; absent when it printed nothing. */
  readonly output?: string;
  readonly tone: SlashCommandTone;
}

/** What one user record turned out to be. */
export type SlashCommandPart =
  | { readonly kind: 'caveat' }
  | { readonly kind: 'command'; readonly command: SlashCommand }
  | { readonly kind: 'output'; readonly output: string; readonly tone: SlashCommandTone };

const TAGS = [
  'local-command-caveat',
  'command-name',
  'command-message',
  'command-args',
  'local-command-stdout',
  'local-command-stderr',
] as const;

type Tag = (typeof TAGS)[number];

const BLOCK = new RegExp(`<(${TAGS.join('|')})>([\\s\\S]*?)</\\1>`, 'gu');

/** Terminal colour and style sequences: Claude bolds the model name in `/model`'s output. */
const ANSI = new RegExp(`${String.fromCharCode(27)}\\[[0-9;?]*[A-Za-z]`, 'gu');

/** A value with its colour codes removed and its edges trimmed; `undefined` when nothing is left. */
const clean = (value: string | undefined): string | undefined => {
  const text = value?.replace(ANSI, '').trim();
  return text === undefined || text === '' ? undefined : text;
};

/** Every known block's content, in order, keyed by tag. */
const blocksOf = (text: string): ReadonlyMap<Tag, readonly string[]> => {
  const found = new Map<Tag, string[]>();
  for (const match of text.matchAll(BLOCK)) {
    const tag = match[1] as Tag;
    found.set(tag, [...(found.get(tag) ?? []), match[2] as string]);
  }
  return found;
};

/** The combined output of every stdout and stderr block, and whether any of it was an error. */
const outputOf = (blocks: ReadonlyMap<Tag, readonly string[]>): { output?: string; tone: SlashCommandTone } => {
  const stderr = (blocks.get('local-command-stderr') ?? []).map(clean).filter(Boolean);
  const stdout = (blocks.get('local-command-stdout') ?? []).map(clean).filter(Boolean);
  const output = [...stdout, ...stderr].join('\n');
  return { ...(output === '' ? {} : { output }), tone: stderr.length > 0 ? 'err' : 'ok' };
};

/** `/model` from either the name block or, failing that, the bare message block. */
const commandName = (blocks: ReadonlyMap<Tag, readonly string[]>): string | undefined => {
  const name = clean(blocks.get('command-name')?.[0]) ?? clean(blocks.get('command-message')?.[0]);
  if (name === undefined) return undefined;
  return name.startsWith('/') ? name : `/${name}`;
};

/**
 * Reads one user record. `null` means it is not slash-command markup at all and
 * should render as whatever it already was.
 */
export const parseSlashCommandText = (text: string): SlashCommandPart | null => {
  if (text.replace(BLOCK, '').trim() !== '') return null;
  const blocks = blocksOf(text);
  if (blocks.size === 0) return null;

  const { output, tone } = outputOf(blocks);
  const name = commandName(blocks);
  if (name !== undefined) {
    const args = clean(blocks.get('command-args')?.[0]);
    return {
      kind: 'command',
      command: { name, ...(args === undefined ? {} : { args }), ...(output === undefined ? {} : { output }), tone },
    };
  }
  const printed = blocks.has('local-command-stdout') || blocks.has('local-command-stderr');
  if (printed) return { kind: 'output', output: output ?? '', tone };
  return { kind: 'caveat' };
};

/** A command with the output that arrived in the record after it. */
export const withCommandOutput = (
  command: SlashCommand,
  output: Extract<SlashCommandPart, { kind: 'output' }>,
): SlashCommand => ({
  ...command,
  ...(output.output === '' ? {} : { output: output.output }),
  tone: output.tone,
});

/** The one line a collapsed row shows: the first line of output that says anything. */
export const commandOutputSummary = (output: string): string =>
  output
    .split('\n')
    .map(line => line.trim())
    .find(line => line !== '') ?? '';

/** Does the output hold more than the summary line shows? */
export const commandOutputIsLong = (output: string): boolean =>
  output.split('\n').filter(line => line.trim() !== '').length > 1;
